<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\{PublicController,InquiryController,EventRegistrationController};
use App\Http\Controllers\Admin\{DashboardController,InquiryController as AdminInquiryController,ContentController,RegistrationController};
Route::middleware('throttle:60,1')->group(function(){
 Route::get('/',[PublicController::class,'home'])->name('home');Route::get('/produk',[PublicController::class,'products'])->name('products');Route::get('/produk/{product:slug}',[PublicController::class,'product'])->name('product');Route::get('/portofolio',[PublicController::class,'portfolios'])->name('portfolios');Route::get('/portofolio/{portfolio}',[PublicController::class,'portfolio'])->name('portfolio');Route::get('/event',[PublicController::class,'events'])->name('events');Route::get('/event/{event}',[PublicController::class,'event'])->name('event');Route::get('/tentang',[PublicController::class,'about'])->name('about');Route::get('/kontak',[PublicController::class,'contact'])->name('contact');
 Route::post('/kontak',[InquiryController::class,'store'])->middleware('throttle:5,1')->name('inquiries.store');Route::post('/event/{event}/daftar',[EventRegistrationController::class,'store'])->middleware('throttle:5,1')->name('events.register');
 Route::get('/sitemap.xml',function(){return response()->view('sitemap',['products'=>\App\Models\Product::active()->get(),'events'=>\App\Models\Event::upcoming()->get()])->header('Content-Type','application/xml');});Route::get('/robots.txt',fn()=>response("User-agent: *\nAllow: /\nSitemap: ".url('/sitemap.xml'),200,['Content-Type'=>'text/plain']));
});
Route::middleware(['auth','role'])->prefix('admin')->name('admin.')->group(function(){Route::get('/',DashboardController::class)->name('dashboard');Route::get('/inquiries', [AdminInquiryController::class,'index'])->name('inquiries.index');Route::get('/inquiries/{inquiry}',[AdminInquiryController::class,'show'])->name('inquiries.show');Route::patch('/inquiries/{inquiry}',[AdminInquiryController::class,'update'])->name('inquiries.update');Route::get('/events/{event}/registrations',[RegistrationController::class,'index'])->name('registrations.index');Route::patch('/events/{event}/registrations/{registration}',[RegistrationController::class,'update'])->name('registrations.update');Route::get('/events/{event}/registrations.csv',[RegistrationController::class,'export'])->name('registrations.export');Route::get('/content/{type}',[ContentController::class,'index'])->name('content.index');Route::get('/content/{type}/create',[ContentController::class,'create'])->name('content.create');Route::post('/content/{type}',[ContentController::class,'save'])->name('content.store');Route::get('/content/{type}/{id}/edit',[ContentController::class,'edit'])->name('content.edit');Route::put('/content/{type}/{id}',[ContentController::class,'save'])->name('content.update');Route::delete('/content/{type}/{id}',[ContentController::class,'destroy'])->name('content.destroy');});
require __DIR__.'/auth.php';
